messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB; /* Sky blue fallback */
            font-family: sans-serif;
        }
        canvas {
            display: block;
        }
        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="ui">Red vs Blue</div>
    <!-- Importing Three.js r160 as ES Module -->
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const FINISH_LINE_Z = 60; // Distance to the finish line
        const TRACK_LENGTH = 120; // Total length of the loop
        const CAR_WIDTH = 2.0;
        const CAR_LENGTH = 4.0;
        const CAR_HEIGHT = 1.0;
        const LANE_OFFSET = 3.5; // Distance between lanes

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        // Position camera behind the cars
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 0, -10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Objects ---

        // 1. Ground
        const groundGeometry = new THREE.PlaneGeometry(TRACK_LENGTH, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -50; // Center vertically
        ground.receiveShadow = true;
        scene.add(ground);

        // 2. Finish Line (Visual)
        const finishLineGeo = new THREE.PlaneGeometry(10, 2);
        const finishLineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.1, FINISH_LINE_Z);
        scene.add(finishLine);

        // 3. Cars (Procedural Geometry)
        function createCar(color, x, z) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(CAR_WIDTH, CAR_HEIGHT, CAR_LENGTH);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = CAR_HEIGHT / 2;
            chassis.castShadow = true;
            chassis.receiveShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH * 0.6, CAR_HEIGHT * 0.6, CAR_LENGTH * 0.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = CAR_HEIGHT * 1.2;
            cabin.position.z = -0.5;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.2, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1, z: 1 }, { x: 1, z: 1 },
                { x: -1, z: -1 }, { x: 1, z: -1 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            carGroup.position.set(x, 0, z);
            return carGroup;
        }

        const redCar = createCar(0xff0000, 0, -40); // Starts further back
        const blueCar = createCar(0x0000ff, 0, -35); // Starts slightly ahead
        scene.add(redCar);
        scene.add(blueCar);

        // --- Logic & State ---
        let racePhase = 'start'; // 'start', 'race', 'finished'
        let time = 0;
        let blueSpeed = 0.4; // Initial speed
        let redSpeed = 0.2;  // Initial speed (slow)

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            // Reset logic: If Red car passes Finish Line, reset race
            if (redCar.position.z >= FINISH_LINE_Z) {
                racePhase = 'reset';
                redCar.position.z = -40;
                blueCar.position.z = -35;
                blueSpeed = 0.4;
                redSpeed = 0.2;
            }

            // Update Speeds
            if (racePhase === 'race') {
                // Blue maintains steady speed
                blueCar.position.z += blueSpeed;

                // Red accelerates
                if (redSpeed < 0.6) {
                    redSpeed += 0.005; // Acceleration
                }
                redCar.position.z += redSpeed;

                // Camera Follow Logic: Smoothly interpolate camera Z towards the leader
                // But clamp it so we don't see the back of the cars
                const leaderZ = Math.max(redCar.position.z, blueCar.position.z);
                const targetCamZ = leaderZ + 15; // Keep camera 15 units behind leader

                // Smooth camera movement
                camera.position.z += (targetCamZ - camera.position.z) * 0.1;

                // Camera X follows the lane offset slightly
                camera.position.x += (0 - camera.position.x) * 0.1;

                // Camera Y stays relatively high
                camera.position.y += (5 - camera.position.y) * 0.1;

            } else if (racePhase === 'reset') {
                // Simple lerp for reset
                redCar.position.z += ( -40 - redCar.position.z ) * 0.1;
                blueCar.position.z += ( -35 - blueCar.position.z ) * 0.1;
            }

            // Camera LookAt target: Look slightly ahead of the leader
            const lookAtZ = Math.max(redCar.position.z, blueCar.position.z) + 20;
            camera.lookAt(0, 0, lookAtZ);

            // Update UI
            const ui = document.getElementById('ui');
            if (redCar.position.z >= FINISH_LINE_Z) {
                ui.innerText = "RED WINS!";
                ui.style.color = "#ff0000";
            } else if (blueCar.position.z >= FINISH_LINE_Z) {
                ui.innerText = "BLUE WINS!";
                ui.style.color = "#0000ff";
            } else {
                ui.innerText = `Red: ${redCar.position.z.toFixed(1)}m | Blue: ${blueCar.position.z.toFixed(1)}m`;
                ui.style.color = "white";
            }

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
